arguments.new_str:
using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
        // Existing documents use "Discriminator", so keep the old property name.
        modelBuilder.Entity<Blog>().HasDiscriminator().HasJsonPropertyName("Discriminator");

        // Breaking change 2: EF 9 uses only the raw key for "id" (e.g. "1").
        // Existing documents store id as "Blog|1". Preserve that format.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<BlogIdValueGenerator>();

        // Breaking change 3: EF 9 Cosmos provider no longer supports HasIndex.
        // Indexes are managed via Cosmos DB indexing policy, not EF.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);

        // Breaking change 4: EF 9 uses parameterized queries by default.
        // Raw SQL like "SELECT * FROM c WHERE c.Discriminator = 'Blog'"
        // must change: c.Discriminator → c["Discriminator"] (reserved word)
        // and queries via LINQ are now parameterized (generally transparent).
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }  }

// Value generator to preserve the legacy "Discriminator|Key" id format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class BlogIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry) => $"Blog|{Guid.NewGuid()}";
}

