        context.SaveChanges();
    }
}

arguments.new_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 5: EF 9 Cosmos provider now uses sync-over-async
        // for sync calls (ToList, SaveChanges) and will throw by default.
        // Either use async methods or set the following in DbContext config:
        //   optionsBuilder.ConfigureWarnings(w =>
        //       w.Ignore(CosmosEventId.SyncNotSupported));
        var blogs = context.Blogs.ToListAsync().GetAwaiter().GetResult();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChangesAsync().GetAwaiter().GetResult();
    }
}

